+.section__link:hover { border-color: var(--accent-dim); }
+
+/* ══════════════════════════════════════════════════════════
+   MARQUEE STRIP
+══════════════════════════════════════════════════════════ */
+.marquee-strip {
+  background: var(--accent); overflow: hidden;
+  padding: 14px 0;
+}
+.marquee-strip__track {
+  display: flex; gap: 0;
+  animation: marquee 28s linear infinite;
+  width: max-content;
+}
+.marquee-strip__track:hover { animation-play-state: paused; }
+.marquee-strip__item {
+  font-size: .8rem; font-weight: 700; letter-spacing: .1em;
+  text-transform: uppercase; color: #0d0d0f;
+  padding: 0 40px;
+  display: flex; align-items: center; gap: 12px;
+}
+.marquee-strip__item::after {
+  content: '◆'; font-size: .55rem;
+}
+
+@keyframes marquee {
+  from { transform: translateX(0); }
+  to   { transform: translateX(-50%); }
+}
+@media (prefers-reduced-motion: reduce) {
+  .marquee-strip__track { animation: none; }
+}
+
+/* ══════════════════════════════════════════════════════════
+   CATEGORY RAIL
+══════════════════════════════════════════════════════════ */
+.category-rail {
+  background: var(--bg-surface);
+  border-top: 1px solid var(--border);
+  border-bottom: 1px solid var(--border);
+}
+.category-rail__inner {
+  max-width: 1280px; margin: 0 auto;
+  padding: 32px 24px;
+  display: flex; gap: 16px; overflow-x: auto;
+  scrollbar-width: none;
+}
+.category-rail__inner::-webkit-scrollbar { display: none; }
+.category-card {
+  flex: 0 0 auto; min-width: 120px;
+  display: flex; flex-direction: column; align-items: center; gap: 12px;
+  padding: 20px 16px; border-radius: var(--radius-md);
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  cursor: pointer;
+  transition: all var(--transition);
+}
+.category-card:hover,
+.category-card:focus-visible {
+  border-color: var(--accent);
+  background: var(--bg-elevated);
+  transform: translateY(-2px);
+  box-shadow: 0 4px 16px var(--accent-glow);
+}
+.category-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
+.category-card__icon {
+  width: 48px; height: 48px; border-radius: var(--radius-sm);
+  background: var(--bg-elevated);
+  display: flex; align-items: center; justify-content: center;
+  font-size: 1.4rem;
+}
+.category-card__label {
+  font-size: .8rem; font-weight: 600;
+  color: var(--text-secondary); text-align: center;
+  white-space: nowrap;
+}
+
+/* ══════════════════════════════════════════════════════════
+   PRODUCT GRID
+══════════════════════════════════════════════════════════ */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
+  gap: 24px;
+}
+
+.product-card {
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  transition: all var(--transition);
+  display: flex; flex-direction: column;
+}
+.product-card:hover {
+  border-color: var(--border-light);
+  box-shadow: var(--shadow-hover);
+  transform: translateY(-3px);
+}
+.product-card__img-wrap {
+  position: relative; aspect-ratio: 1;
+  overflow: hidden; background: var(--bg-elevated);
+}
+.product-card__img-wrap img {
+  width: 100%; height: 100%; object-fit: cover;
+  transition: transform .5s cubic-bezier(.4,0,.2,1);
+}
+.product-card:hover .product-card__img-wrap img { transform: scale(1.06); }
+
+.product-card__badges {
+  position: absolute; top: 12px; left: 12px;
+  display: flex; flex-direction: column; gap: 6px;
+}
+.product-card__wishlist {
+  position: absolute; top: 10px; right: 10px;
+  width: 34px; height: 34px; border-radius: 50%;
+  background: rgba(13,13,15,.7); backdrop-filter: blur(8px);
+  border: 1px solid var(--border-light);
+  display: flex; align-items: center; justify-content: center;
+  color: var(--text-muted);
+  transition: all var(--transition);
+}
+.product-card__wishlist:hover,
+.product-card__wishlist[aria-pressed="true"] { color: var(--red); border-color: var(--red); }
+.product-card__wishlist:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
+
+.product-card__body {
+  padding: 16px 16px 12px; flex: 1;
+  display: flex; flex-direction: column;
+}
+.product-card__category {
+  font-size: .72rem; font-weight: 600;
+  text-transform: uppercase; letter-spacing: .08em;
+  color: var(--text-muted); margin-bottom: 4px;
+}
+.product-card__name {
+  font-size: .97rem; font-weight: 600;
+  color: var(--text-primary); line-height: 1.35;
+  margin-bottom: 8px; flex: 1;
+}
+.product-card__rating {
+  display: flex; align-items: center; gap: 6px;
+  margin-bottom: 12px;
+}
+.stars { color: var(--accent); font-size: .8rem; letter-spacing: 1px; }
+.rating-count { font-size: .75rem; color: var(--text-muted); }
+
+.product-card__price {
+  display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap;
+}
+.price { font-size: 1.15rem; font-weight: 700; color: var(--text-primary); }
+.price--sale { color: var(--red); }
+.price--original {
+  font-size: .9rem; font-weight: 400;
+  color: var(--text-muted); text-decoration: line-through;
+}
+
+.product-card__footer {
+  padding: 12px 16px 16px;
+  border-top: 1px solid var(--border);
+  display: flex; gap: 8px;
+}
+.product-card__add-btn {
+  flex: 1; background: var(--bg-elevated);
+  color: var(--text-primary);
+  font-weight: 600; font-size: .85rem;
+  padding: 9px 14px; border-radius: var(--radius-sm);
+  border: 1px solid var(--border-light);
+  transition: all var(--transition);
+  display: flex; align-items: center; justify-content: center; gap: 6px;
+}
+.product-card__add-btn:hover {
+  background: var(--accent); color: #0d0d0f; border-color: var(--accent);
+}
+.product-card__add-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
+
+/* ══════════════════════════════════════════════════════════
+   DEALS SECTION
+══════════════════════════════════════════════════════════ */
+.deals-section {
+  background: var(--bg-surface);
+  border-top: 1px solid var(--border);
+  border-bottom: 1px solid var(--border);
+}
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 24px;
+}
+.deal-card {
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  padding: 32px;
+  display: flex; gap: 24px; align-items: center;
+  overflow: hidden; position: relative;
+  transition: all var(--transition);
+}
+.deal-card:hover {
+  border-color: var(--border-light);
+  box-shadow: var(--shadow-hover);
+}
+.deal-card--featured {
+  grid-column: span 2;
+  background:
+    radial-gradient(ellipse 70% 100% at 80% 50%, rgba(232,197,109,.07) 0%, transparent 60%),
+    var(--bg-card);
+}
+.deal-card__glow {
+  position: absolute; right: -60px; top: -60px;
+  width: 280px; height: 280px; border-radius: 50%;
+  background: radial-gradient(circle, rgba(232,197,109,.12), transparent 70%);
+  pointer-events: none;
+}
+.deal-card__body { flex: 1; min-width: 0; }
+.deal-card__tag {
+  font-size: .72rem; font-weight: 700; letter-spacing: .1em;
+  text-transform: uppercase; color: var(--accent);
+  margin-bottom: 8px; display: block;
+}
+.deal-card__title {
+  font-family: var(--font-serif);
+  font-size: clamp(1.2rem, 2.5vw, 1.6rem);
+  font-weight: 700; line-height: 1.2;
+  margin-bottom: 8px;
+}
+.deal-card__desc {
+  font-size: .88rem; color: var(--text-secondary);
+  margin-bottom: 20px; max-width: 38ch;
+}
+.deal-card__savings {
+  display: inline-flex; align-items: center; gap: 8px;
+  background: rgba(224,85,85,.12);
+  border: 1px solid rgba(224,85,85,.3);
+  padding: 6px 14px; border-radius: 999px;
+  font-size: .82rem; font-weight: 700; color: var(--red);
+  margin-bottom: 20px;
+}
+.deal-card__timer {
+  display: flex; gap: 8px; align-items: center;
+  margin-bottom: 20px; flex-wrap: wrap;
+}
+.timer-block {
+  background: var(--bg-elevated);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-sm);
+  padding: 6px 10px; text-align: center; min-width: 48px;
+}
+.timer-block__num {
+  font-family: var(--font-serif); font-size: 1.1rem; font-weight: 700;
+  color: var(--text-primary); line-height: 1;
+}
+.timer-block__unit {
+  font-size: .62rem; font-weight: 600; letter-spacing: .06em;
+  text-transform: uppercase; color: var(--text-muted);
+  margin-top: 2px;
+}
+.timer-sep { color: var(--text-muted); font-size: 1.1rem; align-self: flex-start; padding-top: 4px; }
+
+.deal-card__img {
+  flex-shrink: 0; width: 180px; height: 180px;
+  border-radius: var(--radius-md); overflow: hidden;
+  background: var(--bg-elevated);
+}
+.deal-card__img img {
+  width: 100%; height: 100%; object-fit: cover;
+  transition: transform .5s;
+}
+.deal-card:hover .deal-card__img img { transform: scale(1.05); }
+
+@media (max-width: 768px) {
+  .deals-grid { grid-template-columns: 1fr; }
+  .deal-card--featured { grid-column: span 1; }
+  .deal-card { flex-direction: column; }
+  .deal-card__img { width: 100%; height: 200px; }
+}
+
+/* ══════════════════════════════════════════════════════════
+   EDITORIAL / LOOKBOOK
+══════════════════════════════════════════════════════════ */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  grid-template-rows: auto auto;
+  gap: 20px;
+}
+.editorial-card {
+  position: relative; border-radius: var(--radius-lg);
+  overflow: hidden; background: var(--bg-card);
+  cursor: pointer;
+}
+.editorial-card--hero { grid-row: span 2; }
+.editorial-card__img {
+  width: 100%; height: 100%; min-height: 200px; object-fit: cover;
+  transition: transform .6s cubic-bezier(.4,0,.2,1);
+}
+.editorial-card--hero .editorial-card__img { min-height: 480px; }
+.editorial-card:hover .editorial-card__img { transform: scale(1.05); }
+.editorial-card__overlay {
+  position: absolute; inset: 0;
+  background: linear-gradient(to top, rgba(0,0,0,.78) 0%, transparent 55%);
+  display: flex; flex-direction: column; justify-content: flex-end;
+  padding: 24px;
+  transition: background var(--transition);
+}
+.editorial-card:hover .editorial-card__overlay {
+  background: linear-gradient(to top, rgba(0,0,0,.86) 0%, rgba(0,0,0,.1) 60%);
+}
+.editorial-card__tag {
+  font-size: .72rem; font-weight: 700; letter-spacing: .1em;
+  text-transform: uppercase; color: var(--accent);
+  margin-bottom: 6px;
+}
+.editorial-card__title {
+  font-family: var(--font-serif);
+  font-size: clamp(.95rem, 1.8vw, 1.3rem);
+  font-weight: 700; color: #fff; line-height: 1.25;
+  margin-bottom: 10px;
+}
+.editorial-card--hero .editorial-card__title { font-size: clamp(1.4rem, 2.5vw, 2rem); }
+.editorial-card__meta {
+  font-size: .78rem; color: rgba(255,255,255,.55);
+  display: flex; gap: 12px; align-items: center;
+}
+.editorial-card__read-more {
+  font-size: .8rem; font-weight: 600; color: var(--accent);
+  margin-top: 12px; display: inline-flex; align-items: center; gap: 4px;
+  opacity: 0; transform: translateY(6px);
+  transition: opacity var(--transition), transform var(--transition);
+}
+.editorial-card:hover .editorial-card__read-more,
+.editorial-card:focus-within .editorial-card__read-more {
+  opacity: 1; transform: translateY(0);
+}
+.editorial-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
+
+@media (max-width: 900px) {
+  .editorial-grid {
+    grid-template-columns: 1fr 1fr;
+  }
+  .editorial-card--hero { grid-column: span 2; grid-row: span 1; }
+}
+@media (max-width: 580px) {
+  .editorial-grid { grid-template-columns: 1fr; }
+  .editorial-card--hero { grid-column: span 1; }
+}
+
+/* ══════════════════════════════════════════════════════════
+   TESTIMONIALS
+══════════════════════════════════════════════════════════ */
+.testimonials-strip {
+  background: var(--bg-surface);
+  border-top: 1px solid var(--border);
+}
+.testimonials-grid {
+  display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px;
+}
+.testimonial-card {
+  background: var(--bg-card); border: 1px solid var(--border);
+  border-radius: var(--radius-md); padding: 24px;
+}
+.testimonial-card__stars { color: var(--accent); font-size: .9rem; margin-bottom: 12px; }
+.testimonial-card__quote {
+  font-size: .92rem; color: var(--text-secondary);
+  line-height: 1.7; margin-bottom: 16px;
+  font-style: italic;
+}
+.testimonial-card__author {
+  display: flex; align-items: center; gap: 10px;
+}
+.testimonial-card__avatar {
+  width: 36px; height: 36px; border-radius: 50%;
+  background: var(--bg-elevated);
+  display: flex; align-items: center; justify-content: center;
+  font-size: 1rem; flex-shrink: 0;
+  border: 1px solid var(--border-light);
+}
+.testimonial-card__name { font-size: .85rem; font-weight: 600; }
+.testimonial-card__location { font-size: .75rem; color: var(--text-muted); }
+
+@media (max-width: 768px) {
+  .testimonials-grid { grid-template-columns: 1fr; }
+}
+
+/* ══════════════════════════════════════════════════════════
+   NEWSLETTER
+══════════════════════════════════════════════════════════ */
+.newsletter {
+  background: var(--bg-surface);
+  border-top: 1px solid var(--border);
+  border-bottom: 1px solid var(--border);
+}
+.newsletter__inner {
+  max-width: 1280px; margin: 0 auto;
+  padding: 64px 24px;
+  display: grid; grid-template-columns: 1fr 1fr;
+  gap: 48px; align-items: center;
+}
+.newsletter__tag {
+  font-size: .75rem; font-weight: 700; letter-spacing: .1em;
+  text-transform: uppercase; color: var(--accent); margin-bottom: 12px;
+}
+.newsletter__title {
+  font-family: var(--font-serif);
+  font-size: clamp(1.5rem, 3vw, 2rem);
+  font-weight: 700; margin-bottom: 10px;
+}
+.newsletter__desc { font-size: .92rem; color: var(--text-secondary); }
+.newsletter__form { display: flex; gap: 10px; flex-wrap: wrap; }
+.newsletter__input {
+  flex: 1; min-width: 200px;
+  background: var(--bg-card); border: 1px solid var(--border-light);
+  color: var(--text-primary); font-family: var(--font-sans);
+  font-size: .92rem; padding: 13px 18px;
+  border-radius: var(--radius-sm);
+  transition: border-color var(--transition), box-shadow var(--transition);
+}
+.newsletter__input::placeholder { color: var(--text-muted); }
+.newsletter__input:focus {
+  outline: none; border-color: var(--accent);
+  box-shadow: 0 0 0 3px var(--accent-glow);
+}
+.newsletter__perks {
+  margin-top: 14px; display: flex; gap: 16px; flex-wrap: wrap;
+}
+.newsletter__perk {
+  font-size: .78rem; color: var(--text-muted);
+  display: flex; align-items: center; gap: 5px;
+}
+.newsletter__perk::before { content: '✓'; color: var(--green); font-weight: 700; }
+
+@media (max-width: 768px) {
+  .newsletter__inner { grid-template-columns: 1fr; gap: 28px; }
+}
+
+/* ══════════════════════════════════════════════════════════
+   BRANDS BAR
+══════════════════════════════════════════════════════════ */
+.brands-bar {
+  background: var(--bg-base);
+  padding: 40px 24px;
+}
+.brands-bar__label {
+  text-align: center; font-size: .75rem; font-weight: 600;
+  letter-spacing: .1em; text-transform: uppercase;
+  color: var(--text-muted); margin-bottom: 28px;
+}
+.brands-bar__logos {
+  max-width: 960px; margin: 0 auto;
+  display: flex; justify-content: center; align-items: center;
+  flex-wrap: wrap; gap: 12px 32px;
+}
+.brand-logo {
+  font-family: var(--font-serif);
+  font-size: 1.1rem; font-weight: 700; letter-spacing: -.01em;
+  color: var(--text-muted);
+  transition: color var(--transition);
+  padding: 8px 16px; border-radius: var(--radius-sm);
+}
+.brand-logo:hover { color: var(--text-secondary); }
+
+/* ══════════════════════════════════════════════════════════
+   FOOTER
+══════════════════════════════════════════════════════════ */
+.footer {
+  background: var(--bg-surface);
+  border-top: 1px solid var(--border);
+}
+.footer__top {
+  max-width: 1280px; margin: 0 auto;
+  padding: 56px 24px 40px;
+  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 40px;
+}
+.footer__brand-logo {
+  font-family: var(--font-serif); font-size: 1.5rem;
+  font-weight: 700; color: var(--accent); margin-bottom: 14px;
+}
+.footer__brand-desc {
+  font-size: .88rem; color: var(--text-muted);
+  max-width: 30ch; line-height: 1.7; margin-bottom: 20px;
+}
+.footer__socials {
+  display: flex; gap: 8px;
+}
+.footer__social-btn {
+  width: 36px; height: 36px; border-radius: var(--radius-sm);
+  background: var(--bg-card); border: 1px solid var(--border);
+  display: flex; align-items: center; justify-content: center;
+  color: var(--text-muted); font-size: .85rem;
+  transition: all var(--transition);
+}
+.footer__social-btn:hover { color: var(--accent); border-color: var(--accent); }
+.footer__social-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
+
+.footer__col-title {
+  font-size: .8rem; font-weight: 700; letter-spacing: .08em;
+  text-transform: uppercase; color: var(--text-secondary);
+  margin-bottom: 16px;
+}
+.footer__col-links { display: flex; flex-direction: column; gap: 10px; }
+.footer__col-links a {
+  font-size: .88rem; color: var(--text-muted);
+  transition: color var(--transition);
+}
+.footer__col-links a:hover { color: var(--text-primary); }
+
+.footer__bottom {
+  border-top: 1px solid var(--border);
+  max-width: 1280px; margin: 0 auto;
+  padding: 20px 24px;
+  display: flex; align-items: center; justify-content: space-between;
+  flex-wrap: wrap; gap: 12px;
+}
+.footer__copy { font-size: .8rem; color: var(--text-muted); }
+.footer__legal {
+  display: flex; gap: 20px;
+}
+.footer__legal a {
+  font-size: .8rem; color: var(--text-muted);
+  transition: color var(--transition);
+}
+.footer__legal a:hover { color: var(--text-secondary); }
+
+@media (max-width: 900px) {
+  .footer__top { grid-template-columns: 1fr 1fr; }
+}
+@media (max-width: 560px) {
+  .footer__top { grid-template-columns: 1fr; }
+}
+
+/* ══════════════════════════════════════════════════════════
+   CART DRAWER
+══════════════════════════════════════════════════════════ */
+.cart-overlay {
+  position: fixed; inset: 0; z-index: 400;
+  background: rgba(0,0,0,.6); backdrop-filter: blur(4px);
+  opacity: 0; pointer-events: none;
+  transition: opacity .3s;
+}
+.cart-overlay.is-open { opacity: 1; pointer-events: all; }
+
+.cart-drawer {
+  position: fixed; top: 0; right: 0; bottom: 0;
+  z-index: 401; width: 400px; max-width: 100vw;
+  background: var(--bg-surface);
+  border-left: 1px solid var(--border);
+  transform: translateX(100%);
+  transition: transform .35s cubic-bezier(.4,0,.2,1);
+  display: flex; flex-direction: column;
+  box-shadow: -8px 0 40px rgba(0,0,0,.5);
+}
+.cart-drawer.is-open { transform: translateX(0); }
+.cart-drawer__head {
+  padding: 20px 24px;
+  border-bottom: 1px solid var(--border);
+  display: flex; align-items: center; justify-content: space-between;
+}
+.cart-drawer__title { font-family: var(--font-serif); font-size: 1.2rem; font-weight: 700; }
+.cart-drawer__close {
+  width: 36px; height: 36px; border-radius: var(--radius-sm);
+  background: var(--bg-card); border: 1px solid var(--border);
+  display: flex; align-items: center; justify-content: center;
+  color: var(--text-secondary);
+  transition: all var(--transition);
+}
+.cart-drawer__close:hover { color: var(--text-primary); background: var(--bg-elevated); }
+.cart-drawer__close:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
+.cart-drawer__body { flex: 1; overflow-y: auto; padding: 20px 24px; }
+.cart-empty {
+  text-align: center; padding: 48px 0; color: var(--text-muted);
+}
+.cart-empty__icon { font-size: 2.5rem; margin-bottom: 12px; }
+.cart-empty__text { font-size: .92rem; }
+.cart-item {
+  display: flex; gap: 14px; margin-bottom: 16px;
+  padding-bottom: 16px; border-bottom: 1px solid var(--border);
+}
+.cart-item__img {
+  width: 72px; height: 72px; flex-shrink: 0;
+  border-radius: var(--radius-sm); overflow: hidden;
+  background: var(--bg-elevated);
+}
+.cart-item__img img { width: 100%; height: 100%; object-fit: cover; }
+.cart-item__info { flex: 1; min-width: 0; }
+.cart-item__name { font-size: .9rem; font-weight: 600; margin-bottom: 4px; }
+.cart-item__variant { font-size: .78rem; color: var(--text-muted); }
+.cart-item__price { font-size: .9rem; font-weight: 700; color: var(--accent); margin-top: 6px; }
